import {
    BooleanColumn,
    GenericColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    Table,
    TableNameColumn,
    TranslatedFieldColumn,
} from '../../../db'

export const sys_atf_step = Table({
    name: 'sys_atf_step',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        copied_from: ReferenceColumn({
            mandatory: false,
            label: 'Copied from',
            read_only: true,
            active: true,
            referenceTable: 'sys_atf_step',
        }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: true,
            active: true,
            maxLength: 1000,
            dropdown: 'none',
        }),
        display_name: TranslatedFieldColumn({ mandatory: false, label: 'Display name', read_only: true, active: true }),
        inputs: GenericColumn({
            mandatory: false,
            label: 'Input variables',
            read_only: false,
            active: true,
            column_type: 'glide_var',
        }),
        mugshots_cache_json: GenericColumn({
            mandatory: false,
            label: 'Mugshots Cache JSON',
            read_only: true,
            active: true,
            column_type: 'json',
        }),
        notes: StringColumn({
            mandatory: false,
            label: 'Notes',
            read_only: false,
            active: true,
            maxLength: 1000,
            dropdown: 'none',
        }),
        order: IntegerColumn({ mandatory: false, label: 'Execution order', read_only: false, active: true }),
        snapshot: ReferenceColumn({
            mandatory: false,
            label: 'Snapshot',
            read_only: false,
            active: true,
            referenceTable: 'sys_atf_snapshot',
        }),
        step_config: ReferenceColumn({
            mandatory: true,
            label: 'Step config',
            read_only: true,
            active: true,
            referenceTable: 'sys_atf_step_config',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        table: TableNameColumn({ mandatory: false, label: 'Table', read_only: false, active: true }),
        test: ReferenceColumn({
            mandatory: true,
            label: 'Test',
            read_only: true,
            active: true,
            referenceTable: 'sys_atf_test',
        }),
        timeout: GenericColumn({
            mandatory: false,
            label: 'Timeout',
            read_only: false,
            active: true,
            column_type: 'glide_duration',
        }),
        warning_message: StringColumn({
            mandatory: false,
            label: 'Warning message',
            read_only: true,
            active: true,
            maxLength: 1000,
            dropdown: 'none',
        }),
    },
})
